input.code:
const dsl = `workspace "Order Management" "Multi-file Structurizr workspace for the order management domain" {

    !identifiers hierarchical

    model {
customer = person "Customer" "Places orders and tracks their status"
supportAgent = person "Support Agent" "Assists customers and manages orders on their behalf"
orderSystem = softwareSystem "Order Management System" "Handles the order lifecycle from placement to fulfilment" {
    webApp = container "Web Application" "Customer-facing storefront for browsing and placing orders" "React" "Web"
    api = container "Order API" "REST API for order operations" "Node.js" "API"
    worker = container "Order Worker" "Processes order events asynchronously" "Node.js" "Worker"
    db = container "Order Database" "Stores orders and their state" "PostgreSQL" "Database"
    queue = container "Message Queue" "Buffers order events between the API and the worker" "RabbitMQ" "Queue"
}

inventorySystem = softwareSystem "Inventory System" "External system that tracks stock levels" "External"
customer -> orderSystem.webApp "places orders via" "HTTPS"
supportAgent -> orderSystem.api "manages orders via" "HTTPS"
orderSystem.webApp -> orderSystem.api "calls" "HTTPS/JSON"
orderSystem.api -> orderSystem.db "reads and writes orders" "SQL"
orderSystem.api -> orderSystem.queue "publishes order events to" "AMQP" "Async"
orderSystem.worker -> orderSystem.queue "consumes order events from" "AMQP" "Async"
orderSystem.worker -> orderSystem.db "updates order status in" "SQL"
orderSystem.worker -> inventorySystem "reserves stock in" "HTTPS/JSON"
    }

    views {
systemLandscape "Landscape" "All people and systems in the order management domain" {
    include *
    autoLayout
    title "Order Management Landscape"
}

systemContext orderSystem "OrderSystemContext" {
    include *
    autoLayout
    title "System Context for the Order Management System"
}

container orderSystem "OrderSystemContainers" {
    include *
    autoLayout
    title "Containers of the Order Management System"
}

dynamic orderSystem "OrderPlacement" "A customer places an order and it is processed" {
    1: customer -> orderSystem.webApp "submits an order" "HTTPS"
    2: orderSystem.webApp -> orderSystem.api "forwards the order" "HTTPS/JSON"
    3: orderSystem.api -> orderSystem.db "persists the order" "SQL"
    4: orderSystem.api -> orderSystem.queue "publishes an order event" "AMQP"
    5: orderSystem.worker -> orderSystem.queue "consumes the order event" "AMQP"
    6: orderSystem.worker -> inventorySystem "reserves stock" "HTTPS/JSON"
    7: orderSystem.worker -> orderSystem.db "marks the order as confirmed" "SQL"
    autoLayout
    title "Order Placement Flow"
}
styles {
    element "Person" {
        shape Person
        background #08427B
        color #ffffff
    }
    element "Software System" {
        background #1168BD
        color #ffffff
    }
    element "External" {
        background #999999
        color #ffffff
    }
    element "Container" {
        background #438DD5
        color #ffffff
    }
    element "Database" {
        shape Cylinder
    }
    element "Queue" {
        shape Pipe
    }
    element "Web" {
        shape WebBrowser
    }
    element "Worker" {
        shape Robot
    }
    relationship "Relationship" {
        routing Orthogonal
    }
    relationship "Async" {
        style dashed
    }
}
    }
}`;

const [parse, validate, inspect] = await Promise.allSettled([
  tools.structurizr.parse({ dsl }),
  tools.structurizr.validate({ dsl }),
  tools.structurizr.inspect({ dsl }),
]);
const show = (r) => r.status === "fulfilled" ? r.value : { error: r.reason && r.reason.message ? r.reason.message : String(r.reason) };
return { parse: show(parse), validate: show(validate), inspect: show(inspect) };

